/* ── The semantic glyph library ───────────────────────────────────────────────────────
   Pre-treated icon silhouettes: closed filled outlines the engine dresses
   in the kit's full layer cake (face, pattern, bevel wall, extrusion, glow)
   — the same treatment family as type stamps and the gear/trophy/gift
   props. The owner's taxonomy: 8 categories, semantic names.

   GEOMETRY CONTRACT (kernel-safe by construction):
   · absolute M/L/C/Z only — arcs are converted to cubics at bake time,
     because insetShape's reviewed-kernel ladder declines arc paths and
     the scaled-clone fallback is exactly the mangling the bolt round
     root-caused (commit 69797e7)
   · multi-subpath is fine: counter-holes and islands are first-class in
     the offset machinery
   · interiors render as solid silhouette — per-glyph interior furnishing
     (the gear-hub precedent) is deliberate follow-on work, never faked

   SOURCES · LICENSE: most outlines are game-icons.net artwork (CC BY 3.0,
   by Lorc, Delapouite & contributors), extracted from the react-icons
   package this app already ships and embeds in exports; per-entry `source`
   names the original. `energy` is a single-tail revision of PowerLightning
   (owner markup, 2026-08-19: forked tail removed). Entries marked
   "authored in-house" are original geometry.

   Reached through the `glyph:` Shape prefix; the registry alone decides
   what exists — adding an entry here is all a new glyph needs. */

export type GlyphCategory =
  | "Currencies & Resources"
  | "Progression & Achievement"
  | "Boosters & Power-ups"
  | "Rewards & Collections"
  | "Gameplay Status"
  | "Commerce & Economy"
  | "Navigation & System"
  | "Social & Retention";

export interface EngineGlyph {
  id: string;
  name: string;
  category: GlyphCategory;
  /** source box the path was normalized in */
  vb: [number, number, number, number];
  /** absolute M/L/C/Z outline(s), closed */
  d: string;
  /** optional furnishing subpaths (same box, same command contract) the
   *  engine paints in the kit's SHADOW role ink over the face, clipped to
   *  the silhouette — the coin's rim bands are the first tenant.
   *  This is per-glyph interior furnishing arriving as DATA: the geometry
   *  contract stays untouched and glyphs without a detail render exactly
   *  as before. */
  detail?: string;
  /** optional light-catch furnishing (same box/contract) painted in the
   *  kit's HIGHLIGHT role over the shadow pass — the recessed coin face's
   *  lower lip. Paired with `detail`, the two inks speak the engine's
   *  light model: shadow on a recess's upper wall, light catch on its
   *  lower wall — an inset that reads without touching the geometry. */
  detailLight?: string;
  /** authored sparkle seats — the kit's glint star stamped at (x, y),
   *  point-radius s, all in the same box (r° rotation). Kit-following:
   *  opacity/blend ride Typography → Glints while that treatment is on;
   *  otherwise the seats shine at their authored strength. */
  glints?: { x: number; y: number; s: number; r?: number }[];
  source: string;
  license: string;
}

